import{_ as o,o as a,c as r,a5 as t}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"Sequence Flow — View Workspace Dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/sequence-flow.md","filePath":"feature/agency-workspace/3-4-11-view-workspace-dashboard/sequence-flow.md"}'),c={name:"feature/agency-workspace/3-4-11-view-workspace-dashboard/sequence-flow.md"};function s(d,e,i,n,l,p){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="sequence-flow-—-view-workspace-dashboard" tabindex="-1">Sequence Flow — View Workspace Dashboard <a class="header-anchor" href="#sequence-flow-—-view-workspace-dashboard" aria-label="Permalink to &quot;Sequence Flow — View Workspace Dashboard&quot;">​</a></h1><p>&gt; FR 3.4.11 — <strong>Implemented.</strong> Companion to <code>spec.md</code>; lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. &gt; &gt; Updated: 2026-09-25.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — a Workspace member (MANAGER, CREATOR, or CLIENT), via the FE dashboard page.</li><li><strong>WorkspaceController</strong> — <code>GET /api/v1/workspaces/{workspaceId}/dashboard</code>, <code>@RequireRole({MANAGER, CREATOR, CLIENT})</code>.</li><li><strong>WorkspaceServiceImpl</strong> — <code>getDashboard(workspaceId, currentUser)</code>.</li><li><strong>WorkspaceMemberRepository</strong> — active membership rows.</li><li><strong>WorkspaceMediaPackageRepository</strong> — the Workspace&#39;s media package, if any.</li><li><strong>MediaCampaignRepository</strong> — campaigns under that package.</li><li><strong>AiCreditLedgerRepository</strong> — the parent Agency&#39;s AI credit ledger for the current month.</li></ul><hr><h2 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h2><ol><li>Client → WorkspaceController: <code>GET /api/v1/workspaces/{workspaceId}/dashboard</code>.</li><li>WorkspaceController: <code>@RequireRole({MANAGER, CREATOR, CLIENT})</code> — rejects with 403 <code>FORBIDDEN</code> if the caller has no membership row with a qualifying role.</li><li>WorkspaceController → WorkspaceServiceImpl: <code>getDashboard(workspaceId, currentUser)</code>.</li><li>WorkspaceServiceImpl: <code>findWorkspaceOrThrow(workspaceId)</code> — 404 <code>WORKSPACE_NOT_FOUND</code> if the Workspace does not exist.</li><li>WorkspaceServiceImpl: <code>assertMember(workspaceId, currentUser.getId())</code> — 403 <code>WORKSPACE_ACCESS_DENIED</code> if the caller has no <em>active</em> membership row (BR-29).</li><li>WorkspaceServiceImpl → WorkspaceMemberRepository: <code>findByWorkspaceIdAndIsActiveTrue(workspaceId)</code> → active members; grouped by role into <code>membersByRole</code>.</li><li>WorkspaceServiceImpl → WorkspaceMediaPackageRepository: <code>findByWorkspaceId(workspaceId)</code> → the Workspace&#39;s package, or empty.</li><li>WorkspaceServiceImpl → MediaCampaignRepository: <code>findByWorkspaceMediaPackageId(packageId)</code> if a package exists, else an empty list; grouped by <code>CampaignStatus</code> into <code>campaignsByStatus</code>.</li><li>WorkspaceServiceImpl → AiCreditLedgerRepository: <code>findByAgencyIdAndMonth(workspace.getAgencyId(), currentMonth)</code> → the Agency&#39;s ledger row for the current month, or <code>0</code> if absent.</li><li>WorkspaceServiceImpl: assembles <code>WorkspaceDashboardResponse</code> (embedding <code>toResponse(workspace)</code>, active member count/breakdown, campaign count/breakdown, <code>packageNegotiationStatus</code>, <code>agencyId</code>, <code>aiCreditMonth</code>, <code>agencyAiCreditsUsedThisMonth</code>).</li><li>WorkspaceServiceImpl → WorkspaceController → Client: 200 with the dashboard payload.</li><li>Client: renders the stat cards and breakdown lists; an empty Workspace shows zeros/empty lists without error (BR-04).</li></ol><hr><h2 id="error-paths" tabindex="-1">Error Paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error Paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>2</td><td>Caller has no membership row with a qualifying role</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>4</td><td><code>workspaceId</code> does not exist</td><td>404</td><td><code>WORKSPACE_NOT_FOUND</code></td></tr><tr><td>5</td><td>Caller has a membership row but it is not active (or none at all reaching this check)</td><td>403</td><td><code>WORKSPACE_ACCESS_DENIED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Steps 6–9 run as four independent reads against existing repositories — no new query or migration was needed.</li><li><code>packageNegotiationStatus</code> is <code>null</code> when the Workspace has no <code>WorkspaceMediaPackage</code> yet; <code>totalCampaigns</code> is <code>0</code> and <code>campaignsByStatus</code> is empty in that case (BR-04).</li><li><code>agencyAiCreditsUsedThisMonth</code> reflects Agency-wide usage, not this Workspace alone — <code>AiCreditLedger</code> has no <code>workspaceId</code> column.</li><li>The dashboard performs no writes (BR-03).</li></ul>',12)])])}const m=o(c,[["render",s]]);export{k as __pageData,m as default};
